<div class="page-head"><div><h1 id="pageHeading">Add Lab Test</h1><p>Lab Test / Lab Report Master with price for Clinic Billing.</p></div><a class="btn gray" href="lab-test-list.php"><i data-lucide="list"></i> Lab Test List</a></div>
<div class="card form-card"><form id="labTestForm" novalidate><div class="card-header"><div><h2>Lab Test Details</h2><p>Lab Test Code is generated automatically.</p></div></div><div class="card-body"><div class="form-row"><div class="field col-3"><label>Lab Test Code</label><input id="labTestCode" type="text" readonly></div><div class="field col-5"><label for="labTestName" class="required">Lab Test / Report Name</label><input id="labTestName" name="lab_test_name" type="text" maxlength="255" required placeholder="Lab Test / Report Name" data-required-message="Lab Test Name is required."></div><div class="field col-2"><label for="labPrice" class="required">Price</label><input id="labPrice" name="price" type="text" inputmode="decimal" required value="0.00" placeholder="0.00"></div><div class="field col-2"><label for="labStatus" class="required">Status</label><select id="labStatus" name="status" required><option value="1">Active</option><option value="0">Inactive</option></select></div></div><div class="form-row" id="auditRow" hidden><div class="field col-4"><label>Created By</label><input id="createdByName" type="text" readonly></div><div class="field col-4"><label>Created At</label><input id="createdAt" type="text" readonly></div><div class="field col-4"><label>Updated At</label><input id="updatedAt" type="text" readonly></div></div></div><div class="card-footer"><div class="buttons"><button class="btn btn-primary" id="saveButton" type="submit"><i data-lucide="save"></i><span id="saveButtonText">Save Lab Test</span></button><a class="btn gray" href="lab-test-list.php">Cancel</a></div></div></form></div>
<script>(function(window,document){'use strict';var form=document.getElementById('labTestForm'),params=new URLSearchParams(location.search),reference=params.get('ref')||'',viewMode=params.get('view')==='1',saveButton=document.getElementById('saveButton'),actions=[];var statusSelect=GlobalSelect.init('#labStatus',{placeholder:'Select Status'});function dataOf(r){return r&&r.data&&typeof r.data==='object'?r.data:{};}function setSelect(i,e,v){e.value=v==null?'':String(v);if(i&&typeof i.sync==='function')i.sync();e.value=v==null?'':String(v);}async function load(){try{if(reference){var response=await App.api('api/lab-tests.php?ref='+encodeURIComponent(reference)),data=dataOf(response),row=data.record||{};actions=(data.allowed_actions||[]).map(Number);document.getElementById('pageHeading').textContent=viewMode?'View Lab Test':'Edit Lab Test';document.getElementById('saveButtonText').textContent='Update Lab Test';document.getElementById('labTestCode').value=row.lab_test_code||'';form.lab_test_name.value=row.lab_test_name||'';form.price.value=row.price||'0.00';setSelect(statusSelect,form.status,Number(row.status)===0?'0':'1');document.getElementById('createdByName').value=row.created_by_name||'-';document.getElementById('createdAt').value=row.created_at||'-';document.getElementById('updatedAt').value=row.updated_at||'-';document.getElementById('auditRow').hidden=false;if(!viewMode&&actions.indexOf(3)===-1)saveButton.disabled=true;}else{var response=await App.api('api/lab-tests.php?options=1'),data=dataOf(response);actions=(data.allowed_actions||[]).map(Number);document.getElementById('labTestCode').value=data.next_lab_test_code||'';setSelect(statusSelect,form.status,'1');if(actions.indexOf(2)===-1)saveButton.disabled=true;}if(viewMode){Array.prototype.forEach.call(form.querySelectorAll('input,select,textarea'),function(el){el.disabled=true;});saveButton.hidden=true;}if(window.lucide)window.lucide.createIcons();}catch(error){saveButton.disabled=true;App.showError(error,'Unable to prepare Lab Test form.');}}form.addEventListener('submit',async function(event){event.preventDefault();if(viewMode)return;Validation.clearForm(form);if(!Validation.validateForm(form))return;var data=new FormData(form);data.set('action','save');if(reference)data.set('ref',reference);saveButton.disabled=true;try{var response=await App.api('api/lab-tests.php',{method:'POST',body:data});showToast(response.message||'Lab Test saved successfully.',{type:'success',duration:2});setTimeout(function(){location.href='lab-test-list.php';},650);}catch(error){Validation.applyErrors(form,error.errors||{});App.showError(error,'Unable to save Lab Test.');saveButton.disabled=false;}});load();})(window,document);</script></section><?php require __DIR__ . '/include/footer.php'; ?></main></div><script src="assets/js/appearance.js"></script><script>if(window.lucide){window.lucide.createIcons();}</script></body></html>
